cd /tmp/fontfetch && cat > extract.mjs <<'EOF'
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
const files = [
  ['Cormorant+Garamond','css-Cormorant+Garamond.css'],
  ['EB+Garamond','css-EB+Garamond.css'],
  ['IBM+Plex+Mono','css-IBM+Plex+Mono.css'],
]
mkdirSync('out',{recursive:true})
let out = ''
for (const [familyFile,file] of files) {
  const css = readFileSync(file,'utf8')
  const blocks = css.split('@font-face').slice(1)
  for (const b of blocks) {
    if (!b.includes('U+0000-00FF')) continue
    const fam = b.match(/font-family: '([^']+)'/)[1]
    const style = b.match(/font-style: (\w+)/)[1]
    const weight = b.match(/font-weight: (\d+)/)[1]
    const url = b.match(/url\((https:[^)]+)\)/)[1]
    const slug = fam.toLowerCase().replace(/[^a-z0-9]+/g,'-')
    const name = `${slug}-${weight}${style==='italic'?'-italic':''}.woff2`
    const res = await fetch(url)
    if (!res.ok) throw new Error(url+' '+res.status)
    writeFileSync('out/'+name, Buffer.from(await res.arrayBuffer()))
    out += `@font-face {\n  font-family: '${fam}';\n  font-style: ${style};\n  font-weight: ${weight};\n  font-display: swap;\n  src: url('./assets/fonts/${name}') format('woff2');\n}\n`
  }
}
writeFileSync('out/fonts.css', out)
console.log(out)
EOF
node extract.mjs && ls -la out

