 .provision-list{grid-template-columns:repeat(4,1fr)}
 .journal{max-height:none;padding:4px 14px 12px}
 .entry{grid-template-columns:62px 1fr;font-size:12.5px}
 .tabbar{display:grid;grid-template-columns:repeat(4,1fr);position:fixed;left:0;right:0;bottom:0;z-index:40;background:rgba(247,238,219,.97);backdrop-filter:blur(10px);border-top:1px solid var(--line-2);padding-bottom:env(safe-area-inset-bottom)}
 .tabbar button{font-family:mono;font-size:8px;letter-spacing:.12em;text-transform:uppercase;padding:14px 4px;border:0;background:none;color:var(--muted);border-top:2px solid transparent;cursor:pointer;min-height:48px}
 .tabbar button.is-active{color:var(--rust);border-top-color:var(--rust);background:rgba(163,71,31,.04)}
 .toast{bottom:calc(76px + env(safe-area-inset-bottom))}
 .modal-root{padding:12px;align-items:flex-end}
 .modal{max-height:90vh;width:100%}
