 .modal-head h2{font-size:28px}
 .modal-body{padding:12px 18px 18px}
 .modal-actions{padding:12px 18px 16px;flex-wrap:wrap}
 .modal-actions .btn{flex:1;min-width:120px}
 .transport-option{flex-direction:column;align-items:stretch}
 .transport-option .btn{width:100%;align-self:stretch}
 .tally{grid-template-columns:1fr 1fr}
}
@keyframes panelIn{from{opacity:0;transform:translateY(6px)}to{opacity:1}}
