import { createState, quote, maxBuy, tradeBuy, tradeSell, travel, planTravel, useService, buyTransport, netWorth, rankInfo, advanceDay, ADJACENCY, getLoad, getCapacity } from './src/game.js'
import { GOODS, GOOD_ORDER, TRANSPORTS, CITIES } from './src/data.js'

const state = createState()
let trips = 0
let best = 0
export function step() {
  // services
  for (let i = 0; i < 20; i++) {
    if (state.bars.thirst < 70 && state.coins >= 2) useService(state, 'drink')
    else if (state.bars.hunger < 70 && state.coins >= 6) useService(state, 'meal')
    else if (state.bars.energy < 55 && state.coins >= 14) useService(state, 'rest')
    else break
  }
  if (state.coins < 25 && state.bars.energy > 25) { useService(state, 'work'); }
  // upgrade
  const upgrades = ['donkey','camel','horse','ox','wagon']
  for (const id of upgrades) {
    if (id === state.transport) continue
    const t = TRANSPORTS[id]
    const tradein = Math.round(TRANSPORTS[state.transport].price*0.55)
    if (state.coins > (t.price-tradein) + 120 && getLoad(state) <= t.capacity) {
      buyTransport(state, id); break
    }
  }
  // find best trade
  let bestPlan = null
  for (const entry of ADJACENCY[state.city]) {
    const plan = planTravel(state, entry.city)
    if (!plan || plan.blocked) continue
    const max = maxBuy(state, 'wheat') // dummy
    for (const g of GOOD_ORDER) {
      const n = maxBuy(state, g)
      if (n <= 0) continue
      const buy = quote(state, state.city, g, n, 'buy')
      const sell = quote(state, entry.city, g, n, 'sell')
      // rough travel cost in coins + consumption value
      const travelCost = plan.total.fodder * 6 * 0.6 + plan.days * 4
      const profit = (sell - buy) * n - travelCost
      if (profit > 0 && (!bestPlan || profit > bestPlan.profit)) {
        bestPlan = { dest: entry.city, good: g, qty: n, profit, plan }
      }
    }
  }
  if (!bestPlan) {
    // move somewhere random reachable
    const options = ADJACENCY[state.city].filter(e=>!planTravel(state,e.city)?.blocked)
    if (!options.length) return false
    const dest = options[Math.floor(Math.random()*options.length)].city
    const r = travel(state, dest)
    if (!r.ok || state.over) return false
    trips++
    return true
  }
  const buy = tradeBuy(state, bestPlan.good, bestPlan.qty)
  if (!buy.ok) { console.log('buy fail', buy.msg); return false }
  const r = travel(state, bestPlan.dest)
  if (!r.ok) { console.log('travel fail', r.msg); return false }
  if (state.over) { console.log('DIED', state.deathCause); return false }
  const sell = tradeSell(state, bestPlan.good, 1e9)
  trips++
  const worth = netWorth(state)
  if (worth > best) { best = worth; console.log(`trip ${trips} d${state.day} ${CITIES[state.city].name} ${state.transport} worth ${worth} coins ${state.coins} rank ${rankInfo(worth).current.name} [${bestPlan.good} x${bestPlan.qty}]`) }
  if (state.won || worth >= 10000) { console.log('WON', worth, 'trips', trips, 'day', state.day, 'transport', state.transport); return false }
  if (trips > 120) { console.log('LIMIT', worth); return false }
  return true
}
let running = true
while (running) running = step()
console.log('END', { trips, day: state.day, worth: netWorth(state), coins: state.coins, transport: state.transport, rank: rankInfo(netWorth(state)).current.name, profit: state.stats.profit })
EOF
