#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")"
/usr/bin/time -p node "${RUNTIME_DIR:?}/scripts/default-start.mjs"
  border-radius: 2px;
  background: transparent;
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .04em;
  line-height: 1.2;
  color: var(--ink-2);
  cursor: pointer;
  transition: background .15s, color .15s, border-color .15s;
}

.chip-btn:hover {
  border-color: var(--ink-2);
  color: var(--ink);
}

.chip-btn.is-active {
  border-color: var(--ink);
  background: var(--ink);
  color: var(--card);
}

.market-scroll {
  max-height: min(66vh, 680px);
  overflow: auto;
  overscroll-behavior: contain;
}

.market-table {
  width: 100%;
  border-collapse: collapse;
  font-variant-numeric: tabular-nums;
}

.market-table th {
  position: sticky;
  top: 0;
  z-index: 2;
  padding: 8px 12px;
  border-bottom: 1px solid var(--line-2);
  background: #f7edd9;
  font-family: var(--mono);
  font-size: 8.5px;
  font-weight: 500;
  letter-spacing: .14em;
  text-transform: uppercase;
  text-align: left;
  color: var(--muted);
}

.market-table td {
  padding: 7px 12px;
  border-bottom: 1px dotted var(--line);
  vertical-align: middle;
}

.market-table tbody tr { transition: background .12s; }
.market-table tbody tr:hover { background: rgba(163, 71, 31, .045); }

.good-name {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 15px;
  font-weight: 500;
  line-height: 1.2;
}

.good-sub {
  display: block;
  margin-top: 2px;
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .025em;
  color: var(--muted);
}

.tag {
  display: inline-block;
  padding: 1px 4px;
  border: 1px solid;
  border-radius: 2px;
  font-family: var(--mono);
  font-size: 7.5px;
  font-weight: 500;
  letter-spacing: .09em;
  line-height: 1.4;
  text-transform: uppercase;
  white-space: nowrap;
}

.tag--surplus {
  border-color: rgba(60, 103, 75, .35);
  background: rgba(60, 103, 75, .08);
  color: var(--green);
}

.tag--wanted {
  border-color: rgba(163, 71, 31, .3);
  background: rgba(163, 71, 31, .08);
  color: var(--rust);
}

.tag--current {
  border-color: rgba(47, 97, 120, .35);
  background: rgba(47, 97, 120, .08);
  color: var(--blue);
}

.num { text-align: right !important; }

.price {
  font-family: var(--mono);
  font-size: 13.5px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}

.price--sell { color: var(--green-dark); }

.delta {
  display: block;
  margin-top: 1px;
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .01em;
}

.delta.is-cheap { color: var(--green); }
.delta.is-dear { color: var(--red); }
.delta.is-even { color: var(--muted); }

.stock-col { width: 52px; }
.stock-low { color: var(--red); }

.actions-cell {
  width: 126px;
  text-align: right !important;
  white-space: nowrap;
}

.trade-btn {
  min-width: 50px;
  padding: 6px 5px;
  border: 1px solid var(--line-2);
  border-radius: 2px;
  background: transparent;
  font-family: var(--mono);
  font-size: 8.5px;
  line-height: 1;
  letter-spacing: .03em;
  text-transform: uppercase;
  color: var(--ink-2);
  cursor: pointer;
  transition: background .14s, color .14s, border-color .14s;
}

.trade-btn + .trade-btn { margin-left: 4px; }

.trade-btn--buy:hover:not(:disabled) {
  border-color: var(--green);
  background: var(--green);
  color: #fbf4e4;
}

.trade-btn--sell:hover:not(:disabled) {
  border-color: var(--rust);
  background: var(--rust);
  color: #fbf4e4;
}

.trade-btn:disabled {
  opacity: .28;
  cursor: not-allowed;
}

.market-foot {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 20px;
  border-top: 1px solid var(--line);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .015em;
  color: var(--muted);
}

.empty-row {
  padding: 24px 12px !important;
  text-align: center;
  font-style: italic;
  color: var(--muted);
}

/* ── Travel ─────────────────────────────────────────────────────────────── */

.chart-wrap {
  position: relative;
  z-index: 1;
  padding: 9px 12px 5px;

  background-clip: content-box;
}

/* ── Responsive ─────────────────────────────────────────────────────────── */

@media (max-width: 1200px) and (min-width: 901px) {
  .layout {
    grid-template-columns: 290px minmax(0, 1fr);
  }

  .panel--travel { grid-column: 1 / -1; }

  .routes {
    display: grid;
    grid-template-columns: 1fr 1fr;
    max-height: none;
  }

  .route:nth-child(odd) { border-right: 1px dotted var(--line); }

  .chart-wrap { padding-left: 22%; padding-right: 22%; }
}

@media (max-width: 1100px) {
  .top-actions { display: none; }
}

@media (max-width: 900px) {
  body {
    padding-bottom: calc(66px + env(safe-area-inset-bottom));
  }

  .topbar { position: static; }

  .topbar-inner {
    flex-wrap: wrap;
    gap: 10px;
    padding: 11px 14px 10px;
  }

  .brand { margin-right: 0; }
  .brand-mark { width: 29px; height: 29px; font-size: 13px; }
  .brand h1 { font-size: 19px; letter-spacing: .1em; }
  .brand p { font-size: 6.5px; letter-spacing: .13em; margin-top: 4px; }

  .hud {
    order: 3;
    width: 100%;
    justify-content: space-between;
    margin-top: 2px;
    padding-top: 8px;
    border-top: 1px solid var(--line);
  }

  .hud-item {
    flex: 1;
    min-width: 0;
    padding: 0 9px;
  }

  .hud-item:first-child { padding-left: 0; border-left: 0; }
  .hud-item--rank { display: none; }
  .hud-item--place { flex: 1.5; align-items: flex-end; text-align: right; }
  .hud-item strong { font-size: 11.5px; }
  .hud-label { font-size: 6.5px; }

  .page { padding: 13px 12px 16px; }

  .layout {
    display: block;
    padding-top: 0;
  }

  .panel {
    display: none;
    animation: panelIn .22s ease both;
  }

  .panel.is-active { display: block; }

  .panel--journal { margin-top: 0; }

  @keyframes panelIn {
    from { opacity: 0; transform: translateY(5px); }
    to { opacity: 1; transform: none; }
  }

  .panel-head { padding: 13px 14px 10px; }
  .status-block { padding: 12px 14px; }

  .market-top { padding: 15px 14px 12px; gap: 10px; }
  .market-title h2 { font-size: 28px; }
